-- =============================================================================
-- BroTin Box · 0050 Full recipes for every dish (cook book)
--
-- Fills ingredients (per ONE portion), steps, times, equipment and tips for
-- every dish except NVM2 (Lemon Pepper Chicken already has a recipe).
-- Quantities follow the workbook costing (raw qty, oil, curd) and standard
-- home methods. Mum can correct anything on /menu/dishes/[id]; every edit is
-- versioned. The existing "notes" field is left untouched.
-- Generated by scripts/data/recipes-full.mjs.
-- =============================================================================

insert into public.dish_recipes (menu_item_id, ingredients, steps, prep_minutes, cook_minutes, equipment, tips)
select m.id, v.ingredients, v.steps, v.prep, v.cook, v.equipment, v.tips
  from (values
  ($q$NVM1$q$, $q$[{"name":"Chicken breast, boneless skinless","qty":200,"unit":"g","note":"raw; becomes ~150 g cooked"},{"name":"Thick curd (hung, not watery)","qty":30,"unit":"g"},{"name":"Mint leaves","qty":10,"unit":"g","note":"about a small handful, no stems"},{"name":"Coriander leaves with tender stems","qty":8,"unit":"g"},{"name":"Green chilli","qty":1,"unit":"pcs"},{"name":"Ginger garlic paste","qty":5,"unit":"g","note":"1 tsp"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Roasted cumin powder","qty":1,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Salt","qty":2,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp, for the pan"}]$q$::jsonb, $q$["Butterfly or slice the breast into 2 even pieces about 1.5 cm thick. Lightly pound the thick end so it cooks evenly. Make 2–3 shallow slits on each piece.","Grind mint, coriander, green chilli and lemon juice to a thick paste. Use no water (or 1 tsp at most) so the marinade does not run.","Mix the paste into the curd with ginger garlic paste, cumin, garam masala, pepper and salt.","Coat the chicken well, cover and refrigerate at least 1 hour (overnight is fine).","Heat the grill pan on medium-high until hot. Brush with the oil. Shake off extra marinade and place the chicken down. Do not move it for 5 minutes.","Flip and cook 4–5 minutes more. Lower the heat, cover with a lid for 2 minutes.","Check the thickest part: no pink, juices run clear (75 °C if you have a thermometer).","Rest 3 minutes before slicing so the juices stay inside, then pack."]$q$::jsonb, 75, 15, $q$Mixie (small jar), mixing bowl, grill pan or heavy tawa, lid, meat thermometer if available$q$, $q$Hung curd matters: watery curd makes the chicken steam instead of grill. Keep the mint paste bright by grinding it last, just before marinating. Do not marinate in curd for more than 24 hours or the texture goes soft.$q$),
  ($q$NVM3$q$, $q$[{"name":"Chicken breast, boneless skinless","qty":200,"unit":"g","note":"raw; one butterflied steak"},{"name":"Black pepper, coarsely crushed","qty":3,"unit":"g","note":"about 1 tsp, crush fresh"},{"name":"Garlic, finely minced","qty":8,"unit":"g","note":"3 cloves"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Dried mixed herbs or oregano","qty":1,"unit":"g"},{"name":"Paprika or Kashmiri chilli powder","qty":0.5,"unit":"g","note":"for colour"},{"name":"Salt","qty":2,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml"},{"name":"Butter","qty":5,"unit":"g","note":"optional finish; dairy allergen"}]$q$::jsonb, $q$["Butterfly the breast and pound to an even 1 cm thickness between two sheets of plastic.","Rub with half the garlic, the pepper, lemon juice, herbs, chilli powder, salt and half the oil. Rest 30 minutes in the fridge.","Heat the pan on medium-high until very hot. Add the rest of the oil and lay the steak in.","Sear 4 minutes without moving, until a deep golden crust forms. Flip and cook 3–4 minutes.","Lower the heat. Add the butter (optional) and the remaining garlic to the pan and spoon it over the steak for 1 minute.","Check the centre is fully white with clear juices. Rest 3 minutes, then slice across the grain."]$q$::jsonb, 40, 12, $q$Rolling pin or meat mallet, grill pan or heavy tawa, small pan for garlic butter, lid$q$, $q$Crush pepper fresh in a mortar; ready-made powder tastes flat. If the garlic burns, the steak tastes bitter, so add it only at the end. Skipping butter keeps it dairy-free.$q$),
  ($q$NVM4$q$, $q$[{"name":"Chicken breast, boneless skinless","qty":200,"unit":"g","note":"raw"},{"name":"Water for boiling","qty":500,"unit":"ml"},{"name":"Bay leaf","qty":1,"unit":"pcs"},{"name":"Salt for boiling","qty":2,"unit":"g"},{"name":"Garlic, finely chopped","qty":6,"unit":"g","note":"2 cloves"},{"name":"Black pepper, coarsely crushed","qty":2,"unit":"g"},{"name":"Curry leaves","qty":6,"unit":"pcs"},{"name":"Onion, finely chopped","qty":20,"unit":"g","note":"optional"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":3,"unit":"g"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Put chicken, bay leaf and salt into the water. Bring to a boil, then lower to a gentle simmer, lid on, for 15–18 minutes until cooked through.","Take the chicken out and keep 2 tbsp of the stock aside. Cool 5 minutes.","Smash the chicken lightly with a pestle or masher, then pull into coarse shreds with two forks. Keep some texture, not a paste.","Heat the oil in a kadai. Add garlic and curry leaves and fry 30 seconds until fragrant (not brown). Add onion if using and cook 2 minutes.","Add the chicken, pepper and salt. Toss 2–3 minutes on medium heat. Sprinkle the saved stock so it stays juicy.","Turn off the heat, add lemon juice and coriander, toss and pack."]$q$::jsonb, 10, 25, $q$Pot with lid, mortar and pestle or potato masher, kadai$q$, $q$A gentle simmer (not a rolling boil) keeps breast meat tender. The saved stock is the secret to a moist bowl the next hour. Use the rest of the stock for staff soup.$q$),
  ($q$NVM5$q$, $q$[{"name":"Chicken breast, boneless skinless","qty":200,"unit":"g","note":"raw; cut into 2 thick pieces"},{"name":"Water for par-boiling","qty":400,"unit":"ml"},{"name":"Salt for par-boiling","qty":1,"unit":"g"},{"name":"Thick curd","qty":20,"unit":"g"},{"name":"Kashmiri chilli powder","qty":3,"unit":"g","note":"for colour; swap half for smoked paprika if you have it"},{"name":"Ginger garlic paste","qty":5,"unit":"g"},{"name":"Turmeric","qty":0.3,"unit":"g"},{"name":"Cumin powder","qty":1,"unit":"g"},{"name":"Garam masala","qty":1,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Kasuri methi, crushed","qty":0.5,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Salt","qty":1.5,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"},{"name":"Ghee or oil for smoking","qty":1,"unit":"ml","note":"a few drops on the charcoal"}]$q$::jsonb, $q$["Par-boil: simmer the chicken in salted water for only 6–8 minutes (it should be just cooked inside, not falling apart). Drain and pat dry.","Mix curd, chilli powder, ginger garlic paste, turmeric, cumin, garam masala, pepper, kasuri methi, lemon and salt into a thick paste.","Coat the warm chicken and rest 20–30 minutes (warm meat absorbs marinade faster).","Heat the tawa on high. Brush with oil and grill the chicken 2–3 minutes per side until charred spots appear.","For smoke (dhungar): heat a small piece of charcoal on the flame until red. Put it in a small steel bowl, place the bowl on the tawa next to the chicken, drop the ghee on the coal and cover immediately with a lid for 2 minutes.","Remove the coal bowl carefully, check the chicken is cooked through, rest 2 minutes and slice."]$q$::jsonb, 45, 20, $q$Pot, mixing bowl, heavy tawa or grill pan, small steel bowl, tongs, lid, 1 small piece of charcoal (for smoke)$q$, $q$Because the chicken is boiled first, keep the grill short and hot: long grilling dries it out. For a batch, smoke all the pieces together in a big covered vessel with one coal. Never leave the coal unattended near gas.$q$),
  ($q$NVM6$q$, $q$[{"name":"Whole mackerel (ayala), fresh","qty":315,"unit":"g","note":"1 fish; gives ~130 g edible cooked meat"},{"name":"Kashmiri chilli powder","qty":4,"unit":"g"},{"name":"Turmeric","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":1,"unit":"g"},{"name":"Coriander powder","qty":1,"unit":"g"},{"name":"Ginger garlic paste","qty":5,"unit":"g"},{"name":"Lemon juice","qty":10,"unit":"ml"},{"name":"Rice flour","qty":5,"unit":"g","note":"for the crisp coating"},{"name":"Curry leaves","qty":6,"unit":"pcs"},{"name":"Salt","qty":3,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"}]$q$::jsonb, $q$["Clean the fish: cut off fins, remove gills and gut, scrape the scales, rinse well inside and out. Pat completely dry.","Make 3 deep diagonal slits on each side, down to the bone, so the masala gets in and the fish cooks evenly.","Mix chilli, turmeric, pepper, coriander powder, ginger garlic paste, lemon juice, rice flour and salt into a thick paste (add 1–2 tsp water only if needed).","Rub the masala inside the slits and the belly. Rest 30 minutes in the fridge.","Heat the tawa on medium. Spread the oil and lay the curry leaves down, then put the fish on top of the leaves.","Cook 5–6 minutes without touching until the bottom is crisp and releases on its own. Flip carefully with a wide spatula and cook 5–6 minutes more.","Flesh should flake easily from the bone at the thickest part. Pack whole with the \"contains bones\" label."]$q$::jsonb, 45, 14, $q$Knife and scissors for cleaning, mixing bowl, heavy flat tawa, wide spatula$q$, $q$Fresh fish has clear eyes, red gills and firm flesh that springs back; buy the same morning. A dry fish and a hot tawa stop sticking. Always label bones.$q$),
  ($q$VM1$q$, $q$[{"name":"Paneer","qty":100,"unit":"g","note":"1-inch cubes"},{"name":"Hung curd","qty":30,"unit":"g"},{"name":"Kashmiri chilli powder","qty":2,"unit":"g"},{"name":"Turmeric","qty":0.3,"unit":"g"},{"name":"Ginger garlic paste","qty":3,"unit":"g"},{"name":"Tandoori masala or garam masala","qty":1,"unit":"g"},{"name":"Kasuri methi, crushed","qty":0.5,"unit":"g"},{"name":"Chaat masala","qty":0.5,"unit":"g","note":"to finish"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Salt","qty":1.5,"unit":"g"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"}]$q$::jsonb, $q$["Pat the paneer cubes dry with a cloth.","Whisk curd with chilli powder, turmeric, ginger garlic paste, tandoori masala, kasuri methi, lemon and salt into a thick paste.","Fold the paneer in gently so the cubes do not break. Rest 20–30 minutes in the fridge.","Heat the tawa on medium-high and brush with the oil. Place cubes in a single layer.","Cook 1.5–2 minutes per side, turning to colour 3–4 sides, until lightly charred.","Sprinkle chaat masala and pack."]$q$::jsonb, 40, 8, $q$Mixing bowl, non-stick tawa or grill pan, tongs or spatula$q$, $q$Do not overcook: paneer turns rubbery after about 6–7 minutes in total. If the paneer is hard, soak the cubes in hot salted water for 10 minutes before marinating.$q$),
  ($q$VM2$q$, $q$[{"name":"Paneer","qty":100,"unit":"g","note":"1-inch cubes"},{"name":"Thick curd","qty":25,"unit":"g"},{"name":"Mint leaves","qty":8,"unit":"g"},{"name":"Coriander leaves","qty":5,"unit":"g"},{"name":"Green chilli","qty":1,"unit":"pcs"},{"name":"Ginger","qty":2,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Chaat masala","qty":0.5,"unit":"g"},{"name":"Salt","qty":1.5,"unit":"g"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"}]$q$::jsonb, $q$["Grind mint, coriander, green chilli, ginger and lemon juice to a thick paste with no water.","Mix the paste into the curd with cumin and salt.","Pat the paneer dry, coat gently and rest 20 minutes in the fridge.","Heat the tawa on medium, brush with oil and cook the cubes 1.5–2 minutes per side until golden spots appear.","Finish with chaat masala and pack."]$q$::jsonb, 35, 8, $q$Mixie (small jar), mixing bowl, non-stick tawa$q$, $q$Grind the mint just before marinating so it stays green. Medium heat, not high: the herb paste burns faster than tandoori masala.$q$),
  ($q$VM3$q$, $q$[{"name":"Paneer","qty":100,"unit":"g","note":"cubes or thick strips"},{"name":"Onion, thinly sliced","qty":50,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"},{"name":"Cumin seeds","qty":0.5,"unit":"g"},{"name":"Ginger garlic paste","qty":3,"unit":"g"},{"name":"Kashmiri chilli powder","qty":1,"unit":"g"},{"name":"Turmeric","qty":0.2,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Kasuri methi, crushed","qty":0.3,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1.5,"unit":"g"}]$q$::jsonb, $q$["Heat the oil on medium, add cumin seeds and let them crackle.","Add the onion and a pinch of the salt. Cook on LOW for 12–15 minutes, stirring every minute or two, until deep golden-brown and jammy. If it sticks, add 1 tbsp water and scrape. No sugar is needed: slow cooking makes it sweet.","Add ginger garlic paste and cook 1 minute until the raw smell goes.","Add chilli powder, turmeric, garam masala and pepper with 1 tbsp water; stir 30 seconds.","Add paneer and the rest of the salt. Toss gently 2 minutes until coated and hot.","Finish with kasuri methi and coriander."]$q$::jsonb, 10, 20, $q$Heavy kadai or wide pan (non-stick works best), spatula$q$, $q$For a batch, caramelise the onions for all portions together in the morning; it is the slow part. Thin, even slices brown evenly. Do not rush on high heat or the onion burns before it sweetens.$q$),
  ($q$VM4$q$, $q$[{"name":"Firm tofu","qty":150,"unit":"g","note":"1-inch cubes"},{"name":"Hung curd","qty":30,"unit":"g"},{"name":"Kashmiri chilli powder","qty":2,"unit":"g"},{"name":"Turmeric","qty":0.3,"unit":"g"},{"name":"Ginger garlic paste","qty":4,"unit":"g"},{"name":"Tandoori masala or garam masala","qty":1,"unit":"g"},{"name":"Kasuri methi, crushed","qty":0.5,"unit":"g"},{"name":"Chaat masala","qty":0.5,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Salt","qty":2,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"}]$q$::jsonb, $q$["Press the tofu: wrap the block in a clean cloth, put a heavy plate on top for 15 minutes to squeeze out water. Then cut into cubes.","Whisk curd with all spices, lemon and salt into a thick paste.","Coat the tofu and rest 20–30 minutes.","Heat the tawa on medium-high with the oil. Place cubes in a single layer.","Cook 2 minutes per side, turning to brown 3–4 sides. Tofu can take a little longer than paneer and will not go rubbery.","Sprinkle chaat masala and pack."]$q$::jsonb, 45, 10, $q$Clean cloth and a heavy plate (to press tofu), mixing bowl, non-stick tawa$q$, $q$Pressing is what makes tofu absorb flavour and brown instead of steaming. Contains curd, so it is not vegan; for a vegan version swap curd for 1 tsp lemon + 1 tsp oil.$q$),
  ($q$VM5$q$, $q$[{"name":"Firm tofu","qty":150,"unit":"g","note":"1-inch cubes"},{"name":"Mint leaves","qty":10,"unit":"g"},{"name":"Coriander leaves","qty":6,"unit":"g"},{"name":"Green chilli","qty":1,"unit":"pcs"},{"name":"Garlic","qty":3,"unit":"g","note":"1 clove"},{"name":"Ginger","qty":2,"unit":"g"},{"name":"Lemon juice","qty":10,"unit":"ml"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Chaat masala","qty":0.5,"unit":"g"},{"name":"Salt","qty":2,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp; part in marinade, part for the pan"}]$q$::jsonb, $q$["Press the tofu for 15 minutes in a cloth under a heavy plate, then cube.","Grind mint, coriander, chilli, garlic, ginger and lemon juice into a thick paste with no water.","Mix the paste with cumin, salt and half the oil. Coat the tofu and rest 20 minutes.","Heat the tawa on medium with the rest of the oil. Cook the cubes 2 minutes per side until golden.","Finish with chaat masala and pack."]$q$::jsonb, 40, 10, $q$Cloth and heavy plate (to press tofu), mixie (small jar), non-stick tawa$q$, $q$No curd in this one, so it is dairy-free and vegan. Keep the heat at medium so the green paste does not blacken.$q$),
  ($q$VM6$q$, $q$[{"name":"Button mushrooms","qty":150,"unit":"g","note":"wiped clean, halved or thick-sliced"},{"name":"Onion, roughly chopped","qty":60,"unit":"g"},{"name":"Garlic","qty":5,"unit":"g","note":"2 cloves"},{"name":"Ginger","qty":2,"unit":"g"},{"name":"Fresh cream","qty":30,"unit":"g"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"},{"name":"Cumin seeds","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":1,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Kasuri methi, crushed","qty":0.5,"unit":"g"},{"name":"Water","qty":40,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1.5,"unit":"g"}]$q$::jsonb, $q$["Clean the mushrooms with a damp cloth (do not soak them; they drink water and go soggy). Cut into halves or thick slices.","In half the oil, cook onion, garlic and ginger on medium for 4–5 minutes until soft and translucent but NOT brown. Cool slightly and blend smooth with the water.","Heat the rest of the oil on high, add cumin, then the mushrooms. Cook 5–6 minutes, stirring, until their water comes out and dries up and they turn lightly golden.","Add the onion paste, pepper, garam masala and salt. Simmer 3–4 minutes until it thickens.","Turn the heat to the lowest (or off), stir in the cream and kasuri methi. Do not boil hard after the cream goes in or it may split.","Finish with coriander and pack."]$q$::jsonb, 15, 20, $q$Kadai, mixie, spatula$q$, $q$Mushrooms only brown if the pan is hot and not crowded; for big batches cook them in two lots. Low in protein, so it is labelled clearly on the menu.$q$),
  ($q$VM7$q$, $q$[{"name":"Soya chunks, dry","qty":40,"unit":"g","note":"becomes ~110 g cooked"},{"name":"Water for boiling","qty":500,"unit":"ml"},{"name":"Salt for boiling","qty":1,"unit":"g"},{"name":"Mixed veg, finely chopped","qty":50,"unit":"g","note":"carrot, beans, capsicum, onion"},{"name":"Oil","qty":5,"unit":"ml","note":"1 tsp"},{"name":"Cumin seeds","qty":0.5,"unit":"g"},{"name":"Ginger garlic paste","qty":3,"unit":"g"},{"name":"Green chilli, chopped","qty":0.5,"unit":"pcs"},{"name":"Turmeric","qty":0.2,"unit":"g"},{"name":"Kashmiri chilli powder","qty":1,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Boil the water with salt, add the soya chunks and boil 5 minutes until soft and puffed.","Drain, rinse under cold water and squeeze hard by hand. Rinse and squeeze once more; this removes the raw \"soya smell\".","Smash the chunks with a pestle, or pulse 2–3 times in the mixie, to a coarse crumble (not a paste).","Heat oil, add cumin, then ginger garlic paste and green chilli. Cook 30 seconds.","Add the vegetables and cook 3–4 minutes until just tender.","Add turmeric, chilli powder, garam masala, pepper and salt, then the smashed soya. Toss 3–4 minutes on medium until dry and lightly roasted.","Turn off heat, add lemon and coriander, mix and pack."]$q$::jsonb, 20, 15, $q$Pot, strainer, mortar or mixie (pulse), kadai$q$, $q$The double squeeze is the most important step; skipping it leaves a bitter aftertaste. Soya chunks are a soy allergen, flag on the label.$q$),
  ($q$VM8$q$, $q$[{"name":"Whole wheat penne (dry)","qty":100,"unit":"g","note":"contains gluten"},{"name":"Water for boiling pasta","qty":1200,"unit":"ml"},{"name":"Salt for pasta water","qty":6,"unit":"g"},{"name":"Toned milk","qty":220,"unit":"ml"},{"name":"Whole wheat flour (atta)","qty":12,"unit":"g","note":"thickens the sauce; no maida"},{"name":"Butter","qty":7,"unit":"g"},{"name":"Garlic, finely chopped","qty":5,"unit":"g"},{"name":"Fresh cream","qty":15,"unit":"g"},{"name":"Cheese slice","qty":1,"unit":"pcs","note":"about 20 g"},{"name":"Bell peppers (red, yellow, green), diced","qty":50,"unit":"g"},{"name":"Onion, diced","qty":30,"unit":"g"},{"name":"Sweet corn, boiled","qty":25,"unit":"g"},{"name":"Dried oregano","qty":0.5,"unit":"g"},{"name":"Chilli flakes","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Boil the pasta in salted water 1 minute less than the packet says (usually 9–10 minutes). Keep 3 tbsp pasta water, then drain.","In the sauce pan melt half the butter, add garlic and onion and cook 2 minutes. Add bell peppers and corn and cook 2 minutes more (keep a crunch). Move to a plate.","Melt the rest of the butter on low, add the atta and stir 1 minute until it smells nutty (do not brown).","Pour in the milk slowly while whisking so no lumps form. Cook on low-medium 3–4 minutes, stirring, until it coats the back of a spoon.","Tear in the cheese slice and add the cream, salt, pepper, oregano and chilli flakes. Stir until smooth.","Add the pasta and vegetables and toss 1 minute. If thick, loosen with the saved pasta water."]$q$::jsonb, 10, 20, $q$Large pot for pasta, colander, heavy pan for the sauce, whisk$q$, $q$Portion is 100 g dry pasta. The sauce thickens as it cools in the box, so pack it slightly looser than you would serve at home. Contains gluten (wheat) and dairy.$q$),
  ($q$CD1$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Beetroot, boiled and grated","qty":30,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":1,"unit":"g"},{"name":"Salt","qty":0.5,"unit":"g"}]$q$::jsonb, $q$["Boil or pressure cook the beetroot whole with skin (1–2 whistles or 15 minutes boiling) until a knife goes in easily. Cool, peel and grate.","Whisk the curd until smooth.","Fold in the beetroot, cumin and pepper. It turns pink.","Add salt and coriander just before packing; keep chilled until it leaves the kitchen."]$q$::jsonb, 5, 15, $q$Small pot, grater, mixing bowl, whisk$q$, $q$Boil beetroot for all portions the night before and refrigerate. Salt makes curd release water, so add it at packing time.$q$),
  ($q$CD2$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Mint leaves, finely chopped","qty":3,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Black salt (kala namak)","qty":0.3,"unit":"g","note":"optional"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Whisk the curd until smooth.","Mix in the mint and roasted cumin.","Add salt and black salt just before packing; keep chilled."]$q$::jsonb, 5, 0, $q$Mixing bowl, whisk, knife$q$, $q$Roast cumin seeds dry on a tawa until dark and fragrant, then powder; fresh roasted cumin makes this taste like a restaurant raita.$q$),
  ($q$CD3$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Carrot, finely grated","qty":40,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Coriander leaves, chopped","qty":1,"unit":"g"},{"name":"Salt","qty":0.5,"unit":"g"}]$q$::jsonb, $q$["Peel and finely grate the carrot.","Whisk the curd smooth and fold in carrot and cumin.","Add salt and coriander just before packing; keep chilled."]$q$::jsonb, 8, 0, $q$Grater, mixing bowl, whisk$q$, $q$Optional South Indian touch: a tempering of 1/4 tsp oil, mustard seeds and 3 curry leaves poured on top (adds about 10 kcal).$q$),
  ($q$CD4$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Potato, boiled, peeled, small cubes","qty":40,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":1,"unit":"g"},{"name":"Salt","qty":0.5,"unit":"g"}]$q$::jsonb, $q$["Boil the potato until just tender (2 whistles or 12–15 minutes). Cool fully, peel and cut into small cubes.","Whisk the curd and fold in potato, cumin and pepper.","Add salt and coriander just before packing; keep chilled."]$q$::jsonb, 5, 15, $q$Small pot or pressure cooker, mixing bowl, whisk$q$, $q$Use completely cool potato; warm potato makes the curd sour and runny.$q$),
  ($q$CD5$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Cucumber, deseeded and diced","qty":40,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Mint or coriander, chopped","qty":1,"unit":"g"},{"name":"Salt","qty":0.5,"unit":"g"}]$q$::jsonb, $q$["Peel the cucumber, scoop out the watery seeds with a spoon and dice small.","Whisk the curd and fold in cucumber and cumin.","Add salt and herbs just before packing; keep chilled."]$q$::jsonb, 8, 0, $q$Knife, mixing bowl, whisk$q$, $q$Removing the seeds and adding salt late stops the raita going watery by lunch time.$q$),
  ($q$CD6$q$, $q$[{"name":"Fresh thick curd","qty":100,"unit":"g"},{"name":"Sweet corn kernels, boiled","qty":30,"unit":"g"},{"name":"Roasted cumin powder","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":1,"unit":"g"},{"name":"Salt","qty":0.5,"unit":"g"}]$q$::jsonb, $q$["Boil corn kernels 4–5 minutes, drain and cool completely.","Whisk the curd and fold in corn, cumin and pepper.","Add salt and coriander just before packing; keep chilled."]$q$::jsonb, 5, 6, $q$Small pot, strainer, mixing bowl, whisk$q$, $q$Frozen corn works fine; boil it straight from frozen for 3 minutes.$q$),
  ($q$NVE$q$, $q$[{"name":"Eggs","qty":2,"unit":"pcs","note":"about 100 g"},{"name":"Water","qty":600,"unit":"ml","note":"enough to cover by 2 cm"},{"name":"Salt","qty":0.3,"unit":"g","note":"small sachet or pinch on top"},{"name":"Black pepper powder","qty":0.2,"unit":"g"}]$q$::jsonb, $q$["Take eggs out of the fridge 15 minutes before, so they do not crack.","Place eggs in the pot and cover with cold water by 2 cm. Bring to a boil on high.","As soon as it boils, lower to a gentle simmer and cook 10 minutes for a fully firm yolk.","Move eggs straight into ice-cold water for 5 minutes. This stops the grey ring and makes peeling easy.","Tap all over, peel under running water, pat dry. Halve or pack whole with salt and pepper."]$q$::jsonb, 2, 15, $q$Pot with lid, bowl of ice-cold water, slotted spoon$q$, $q$Eggs 5–7 days old peel much easier than very fresh ones. Pack the yolk in; the label says customers may remove it.$q$),
  ($q$SL1$q$, $q$[{"name":"Sweet corn kernels","qty":60,"unit":"g","note":"boiled"},{"name":"Onion, finely chopped","qty":10,"unit":"g"},{"name":"Tomato, deseeded, chopped","qty":15,"unit":"g"},{"name":"Cucumber, deseeded, chopped","qty":15,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Chaat masala","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Boil corn 4–5 minutes, drain and cool completely.","Chop onion, deseeded tomato and deseeded cucumber small, the size of corn kernels.","Mix corn and vegetables.","Just before packing add lemon, chaat masala, pepper, salt and coriander and toss."]$q$::jsonb, 10, 6, $q$Small pot, strainer, knife, mixing bowl$q$, $q$Total 100 g per box. Deseed tomato and cucumber, and dress at packing time, so it stays crunchy, not soggy.$q$),
  ($q$SL2$q$, $q$[{"name":"Cucumber, deseeded, diced","qty":25,"unit":"g"},{"name":"Tomato, deseeded, diced","qty":20,"unit":"g"},{"name":"Carrot, diced or julienned","qty":20,"unit":"g"},{"name":"Capsicum (mixed colours), diced","qty":20,"unit":"g"},{"name":"Onion, diced","qty":10,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Wash all vegetables, deseed cucumber and tomato.","Cut everything into the same small dice so every spoon gets every colour.","Mix the vegetables.","Just before packing add lemon, pepper, salt and coriander and toss."]$q$::jsonb, 12, 0, $q$Knife, chopping board, mixing bowl$q$, $q$Total ~100 g. Red and yellow capsicum make it look "rainbow"; if only green is available, add a little extra carrot.$q$),
  ($q$SL3$q$, $q$[{"name":"Cabbage, finely shredded","qty":70,"unit":"g"},{"name":"Carrot, grated or julienned","qty":25,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Black pepper, freshly crushed","qty":0.3,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Remove the outer leaves and the hard core of the cabbage. Shred very thin.","Soak the shredded cabbage in cold water 5 minutes for extra crunch, then drain very well.","Mix with carrot.","Just before packing add lemon, pepper, salt and coriander and toss."]$q$::jsonb, 10, 0, $q$Sharp knife or grater, mixing bowl$q$, $q$Thin shredding is everything here: thick cabbage tastes raw and hard. Drain well, extra water dilutes the lemon.$q$),
  ($q$SL4$q$, $q$[{"name":"Cucumber, thin slices","qty":80,"unit":"g"},{"name":"Onion, thin slices","qty":15,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Black pepper, freshly crushed","qty":0.3,"unit":"g"},{"name":"Mint or coriander, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Peel the cucumber in stripes (leave some skin for colour) and slice thin.","Slice the onion thin and separate the rings.","Mix cucumber and onion.","Just before packing add lemon, pepper, salt and herbs."]$q$::jsonb, 8, 0, $q$Knife or slicer, mixing bowl$q$, $q$Salt pulls water out of cucumber fast, so this one must be dressed right at packing time.$q$),
  ($q$SL5$q$, $q$[{"name":"Carrot, finely grated","qty":75,"unit":"g"},{"name":"Fresh coconut, grated","qty":15,"unit":"g"},{"name":"Green chilli, finely chopped","qty":0.5,"unit":"pcs"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Oil","qty":1.2,"unit":"ml","note":"1/4 tsp, for tempering"},{"name":"Mustard seeds","qty":0.3,"unit":"g"},{"name":"Curry leaves","qty":4,"unit":"pcs"},{"name":"Asafoetida (hing)","qty":1,"unit":"pinch"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Mix grated carrot, coconut and green chilli.","Heat the oil in a small pan, add mustard seeds; when they splutter add curry leaves and hing, then pour over the salad.","Just before packing add lemon, salt and coriander and toss."]$q$::jsonb, 10, 2, $q$Grater, mixing bowl, small tadka pan$q$, $q$Kosambari style, no dairy. Use fresh coconut the same day; it spoils quickly in heat.$q$),
  ($q$SL6$q$, $q$[{"name":"Beetroot, peeled and grated","qty":45,"unit":"g","note":"raw"},{"name":"Carrot, grated","qty":25,"unit":"g"},{"name":"Cucumber, deseeded, diced","qty":15,"unit":"g"},{"name":"Onion, finely chopped","qty":10,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Black pepper powder","qty":0.2,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.3,"unit":"g"}]$q$::jsonb, $q$["Peel and grate the beetroot and carrot.","Add the cucumber and onion.","Just before packing add lemon, pepper, salt and coriander and toss."]$q$::jsonb, 12, 0, $q$Grater, knife, mixing bowl, gloves (beet stains)$q$, $q$Beetroot colour bleeds, so keep it in its own compartment, away from curd and rice. Lemon brightens the colour. No dairy.$q$),
  ($q$LG1$q$, $q$[{"name":"Black chana (kala chana), dry","qty":35,"unit":"g","note":"becomes ~100 g boiled"},{"name":"Water for soaking","qty":150,"unit":"ml"},{"name":"Water for cooking","qty":150,"unit":"ml"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"},{"name":"Mustard seeds","qty":0.5,"unit":"g"},{"name":"Urad dal","qty":1,"unit":"g"},{"name":"Curry leaves","qty":5,"unit":"pcs"},{"name":"Dry red chilli or green chilli","qty":0.5,"unit":"pcs"},{"name":"Asafoetida (hing)","qty":1,"unit":"pinch"},{"name":"Fresh coconut, grated","qty":5,"unit":"g","note":"optional"},{"name":"Lemon juice","qty":3,"unit":"ml"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Wash and soak the chana overnight, 8–10 hours.","Drain, add fresh water and salt, and pressure cook 5–6 whistles on medium (about 20 minutes) until soft but holding shape. Drain well.","Heat oil, add mustard seeds; when they splutter add urad dal and fry until golden, then curry leaves, chilli and hing.","Add the chana and toss 2 minutes. Add coconut (optional), turn off heat and add lemon."]$q$::jsonb, 600, 30, $q$Bowl for soaking, pressure cooker, small kadai for tempering$q$, $q$This is classic chana sundal. Soak the chana for tomorrow every evening. If a chana squashes between two fingers, it is cooked.$q$),
  ($q$LG2$q$, $q$[{"name":"Horse gram (kollu), dry","qty":35,"unit":"g"},{"name":"Water for soaking","qty":150,"unit":"ml"},{"name":"Onion, finely chopped","qty":10,"unit":"g","note":"optional"},{"name":"Black pepper, freshly crushed","qty":0.5,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.8,"unit":"g"}]$q$::jsonb, $q$["Pick out stones (kollu often has small stones), wash, and soak 8–10 hours.","Drain, tie in a wet muslin cloth or put in a sprouting box, and keep in a warm dark place 24–36 hours until short tails appear. Sprinkle water if it dries.","Steam the sprouts 12–15 minutes in an idli cooker or steamer. Kollu is hard: if still too firm, pressure cook with a little water for 1–2 whistles instead.","Toss warm with salt, pepper, onion, lemon and coriander. No oil."]$q$::jsonb, 600, 15, $q$Bowl for soaking, sprouting box or wet muslin cloth, steamer or idli cooker$q$, $q$Start the soak 2 days before the dish is on the menu. Kollu sprouts more slowly than green gram. Rinse sprouts once a day so they do not smell sour.$q$),
  ($q$LG3$q$, $q$[{"name":"Green gram (whole moong), dry","qty":30,"unit":"g","note":"gives ~90–100 g sprouts"},{"name":"Water for soaking","qty":120,"unit":"ml"},{"name":"Onion, finely chopped","qty":10,"unit":"g","note":"optional"},{"name":"Tomato, deseeded, chopped","qty":10,"unit":"g","note":"optional"},{"name":"Black pepper, freshly crushed","qty":0.5,"unit":"g"},{"name":"Lemon juice","qty":5,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":0.8,"unit":"g"}]$q$::jsonb, $q$["Wash and soak the moong 8 hours.","Drain, tie in a wet cloth or sprouting box for 12–24 hours until tails are 0.5–1 cm long.","Steam 5–7 minutes only, so they are cooked but still crunchy.","Toss with salt, pepper, onion, tomato, lemon and coriander. No oil."]$q$::jsonb, 1200, 7, $q$Bowl for soaking, sprouting box or wet muslin cloth, steamer$q$, $q$Do not skip steaming: raw sprouts can carry bacteria, which is a risk for a delivery kitchen. Long tails (more than 2 cm) taste bitter.$q$),
  ($q$LG4$q$, $q$[{"name":"Raw peanuts, shelled","qty":35,"unit":"g"},{"name":"Water for soaking","qty":120,"unit":"ml"},{"name":"Water for cooking","qty":150,"unit":"ml"},{"name":"Salt","qty":1,"unit":"g"},{"name":"Black pepper powder","qty":0.3,"unit":"g","note":"optional"},{"name":"Lemon juice","qty":3,"unit":"ml","note":"optional"},{"name":"Coriander leaves, chopped","qty":1,"unit":"g","note":"optional"}]$q$::jsonb, $q$["Soak the peanuts 3–4 hours (optional, but they cook faster and softer).","Pressure cook with fresh water and salt for 3–4 whistles (or boil in an open pot 25–30 minutes) until soft to bite.","Drain and toss with pepper, lemon and coriander while warm."]$q$::jsonb, 240, 25, $q$Bowl for soaking, pressure cooker, strainer$q$, $q$Peanut is a major allergen: keep it on the label and menu, and use a separate spoon and bowl so it does not touch other dishes.$q$),
  ($q$LG5$q$, $q$[{"name":"Rajma (red kidney beans), dry","qty":35,"unit":"g"},{"name":"Water for soaking","qty":150,"unit":"ml","note":"throw this water away"},{"name":"Water for cooking","qty":200,"unit":"ml"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"},{"name":"Cumin seeds","qty":0.5,"unit":"g"},{"name":"Onion, finely chopped","qty":20,"unit":"g"},{"name":"Tomato, finely chopped","qty":25,"unit":"g"},{"name":"Ginger garlic paste","qty":3,"unit":"g"},{"name":"Kashmiri chilli powder","qty":1,"unit":"g"},{"name":"Coriander powder","qty":1,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Wash and soak the rajma 10–12 hours. Throw away the soaking water.","Pressure cook in fresh water with salt: 1 whistle on high, then 15–20 minutes on low (about 6–8 whistles). Every bean must be fully soft and squash easily.","Heat oil, add cumin, then onion; cook until golden. Add ginger garlic paste for 1 minute, then tomato and spices; cook until soft.","Add the drained rajma with 2–3 tbsp of the cooking liquid. Simmer 3–4 minutes until the masala coats the beans. Finish with coriander."]$q$::jsonb, 720, 40, $q$Bowl for soaking, pressure cooker, kadai$q$, $q$SAFETY: undercooked kidney beans contain a natural toxin that causes vomiting. Never slow-cook or serve rajma that is still firm. Always soak, discard the water, and boil fully.$q$),
  ($q$LG6$q$, $q$[{"name":"Green peas (fresh or frozen)","qty":100,"unit":"g"},{"name":"Water for boiling","qty":400,"unit":"ml"},{"name":"Salt","qty":1,"unit":"g"},{"name":"Black pepper powder","qty":0.3,"unit":"g"},{"name":"Lemon juice","qty":3,"unit":"ml"},{"name":"Mint or coriander, chopped","qty":1,"unit":"g"}]$q$::jsonb, $q$["Bring salted water to a rolling boil.","Add the peas: frozen 2–3 minutes, fresh 4–6 minutes, until just tender and bright green.","Drain and toss with pepper, lemon and herbs."]$q$::jsonb, 2, 8, $q$Pot, strainer$q$, $q$Over-boiled peas go grey and mushy. A tiny pinch of sugar in the water helps if fresh peas are starchy.$q$),
  ($q$CB1$q$, $q$[{"name":"Whole wheat atta","qty":70,"unit":"g","note":"makes 2 chapatis of 35 g"},{"name":"Warm water","qty":45,"unit":"ml","note":"add slowly; atta varies"},{"name":"Salt","qty":0.5,"unit":"g"},{"name":"Oil","qty":2,"unit":"ml","note":"a thin film, brushed after cooking"},{"name":"Extra atta for dusting","qty":5,"unit":"g"}]$q$::jsonb, $q$["Mix atta and salt, add warm water little by little and knead 5–7 minutes into a soft, smooth dough that does not stick to your hand.","Cover and rest at least 20 minutes. This is what makes chapatis soft.","Divide into 35 g balls. Dust and roll evenly into thin 6–7 inch circles.","Put on a hot tawa. Flip when small bubbles appear (about 20 seconds). Cook the second side 30 seconds until brown spots form.","Flip again and press gently with a cloth (or hold on the open flame with tongs) so it puffs.","Brush lightly with oil and stack in a cloth-lined casserole straight away."]$q$::jsonb, 30, 6, $q$Mixing bowl, rolling board and pin, heavy tawa, cloth-lined casserole$q$, $q$Rolling evenly is what makes it puff. Pack only after the stack has cooled a little in the casserole, otherwise steam makes them soggy.$q$),
  ($q$CB2$q$, $q$[{"name":"Rolled oats","qty":50,"unit":"g"},{"name":"Mixed veg, finely chopped","qty":40,"unit":"g","note":"onion, carrot, beans, peas, tomato"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"},{"name":"Mustard or cumin seeds","qty":0.5,"unit":"g"},{"name":"Ginger, grated","qty":2,"unit":"g"},{"name":"Green chilli, chopped","qty":0.5,"unit":"pcs"},{"name":"Turmeric","qty":0.2,"unit":"g"},{"name":"Kashmiri chilli powder","qty":0.5,"unit":"g"},{"name":"Garam masala","qty":0.5,"unit":"g"},{"name":"Water","qty":200,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Heat oil, add mustard or cumin seeds, then ginger and green chilli.","Add the vegetables (tomato last) and cook 3–4 minutes.","Add turmeric, chilli powder, garam masala and salt, then the water. Bring to a boil.","Add oats, stir and cook 3–4 minutes on low until creamy.","Finish with coriander."]$q$::jsonb, 10, 12, $q$Kadai or saucepan with lid$q$, $q$Oats keep absorbing water, so pack it looser than you want it to eat. Add 2–3 tbsp hot water just before packing if it has set.$q$),
  ($q$CB3$q$, $q$[{"name":"Rolled oats","qty":50,"unit":"g"},{"name":"Oil","qty":2.5,"unit":"ml","note":"1/2 tsp"},{"name":"Mustard seeds","qty":0.5,"unit":"g"},{"name":"Urad dal","qty":1,"unit":"g"},{"name":"Curry leaves","qty":6,"unit":"pcs"},{"name":"Green chilli, slit","qty":0.5,"unit":"pcs"},{"name":"Ginger, chopped","qty":2,"unit":"g"},{"name":"Onion, chopped","qty":20,"unit":"g"},{"name":"Carrot, finely chopped","qty":15,"unit":"g"},{"name":"Beans or peas","qty":10,"unit":"g"},{"name":"Water","qty":70,"unit":"ml","note":"sprinkled"},{"name":"Lemon juice","qty":3,"unit":"ml"},{"name":"Coriander leaves, chopped","qty":2,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Dry roast the oats in the kadai on low 3–4 minutes until lightly golden and nutty. Set aside.","Heat oil, add mustard seeds; when they splutter add urad dal and fry until golden, then curry leaves, chilli and ginger.","Add onion and cook until soft, then carrot and beans with salt; cover and cook 3 minutes.","Add the roasted oats, sprinkle the water little by little and toss. Cover and steam 2 minutes on low.","Fluff with a fork, add lemon and coriander."]$q$::jsonb, 10, 12, $q$Kadai with lid$q$, $q$Roasting the oats first is what keeps upma fluffy and separate instead of porridge-like. Sprinkle water, never pour.$q$),
  ($q$CB4$q$, $q$[{"name":"Rolled oats","qty":40,"unit":"g","note":"powdered"},{"name":"Moong dal (yellow), dry","qty":15,"unit":"g","note":"soaked 2 hours"},{"name":"Ginger","qty":2,"unit":"g"},{"name":"Green chilli","qty":0.5,"unit":"pcs"},{"name":"Cumin seeds","qty":0.5,"unit":"g"},{"name":"Black pepper, crushed","qty":0.5,"unit":"g"},{"name":"Curry leaves, chopped","qty":3,"unit":"pcs"},{"name":"Water","qty":90,"unit":"ml","note":"adjust to batter"},{"name":"Ghee","qty":2.5,"unit":"ml","note":"1/2 tsp, for both dosas"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Soak moong dal 2 hours. Powder the oats in a dry mixie.","Grind the soaked dal with ginger, chilli and a little water to a smooth paste. Add oats powder, salt and remaining water to a pouring batter (like regular dosa batter).","Stir in cumin, pepper and curry leaves. Rest 15 minutes (oats thicken it; add water if needed).","Heat the tawa on medium-high. Pour a ladle and spread thin from the centre outward.","Drizzle ghee on the edges. Cook until the bottom is golden and crisp, about 2 minutes; flip for 30 seconds if you like. Makes 2 dosas."]$q$::jsonb, 135, 10, $q$Bowl for soaking, mixie, non-stick dosa tawa, ladle$q$, $q$Wipe the tawa with a wet cloth or a little water between dosas so the batter spreads. Pack folded; they soften a little in the box, which is normal.$q$),
  ($q$CB5$q$, $q$[{"name":"Millet dosa batter (variety of the day)","qty":130,"unit":"g","note":"enough for 2 dosas; ragi, kambu, thinai, varagu, samai, jowar etc."},{"name":"Oil or ghee","qty":2.5,"unit":"ml","note":"1/2 tsp, for both dosas"},{"name":"Salt","qty":null,"unit":"to taste","note":"only if the batter is not already salted"},{"name":"Water","qty":null,"unit":"to taste","note":"to bring batter to pouring consistency"}]$q$::jsonb, $q$["Make the day's millet batter the way that variety needs (soaked and ground, or instant flour + curd). Roughly 50 g dry millet/flour gives 2 dosas.","Stir the batter well before every dosa (millet settles at the bottom). Add a little water if it has thickened.","Heat the tawa on medium-high. Sprinkle water: it should sizzle away at once. Wipe with a wet cloth.","Pour one ladle (about 65 g) in the centre and spread thin in circles from the middle outward.","Drizzle oil on the edges. Cook 2–3 minutes until the bottom is golden and crisp and the edges lift.","Fold and remove. Make the second dosa the same way. Pack 2 dosas per portion."]$q$::jsonb, 15, 10, $q$Non-stick or cast-iron dosa tawa, ladle, wet cloth to wipe the tawa$q$, $q$Assorted dish: the millet rotates by day, so the batter recipe lives with the cook, and this card covers the portion and cooking method. Keep every variety at about 50 g dry millet/flour (130 g batter) for 2 dosas so calories and cost stay the same. Millet batter needs a hot tawa and a thin spread to crisp up.$q$),
  ($q$CB6$q$, $q$[{"name":"Whole wheat penne (dry)","qty":100,"unit":"g","note":"contains gluten"},{"name":"Water for boiling pasta","qty":1200,"unit":"ml"},{"name":"Salt for pasta water","qty":6,"unit":"g"},{"name":"Toned milk","qty":220,"unit":"ml"},{"name":"Whole wheat flour (atta)","qty":12,"unit":"g","note":"thickens the sauce; no maida"},{"name":"Butter","qty":7,"unit":"g"},{"name":"Garlic, finely chopped","qty":5,"unit":"g"},{"name":"Fresh cream","qty":15,"unit":"g"},{"name":"Cheese slice","qty":1,"unit":"pcs","note":"about 20 g"},{"name":"Bell peppers (red, yellow, green), diced","qty":50,"unit":"g"},{"name":"Onion, diced","qty":30,"unit":"g"},{"name":"Sweet corn, boiled","qty":25,"unit":"g"},{"name":"Dried oregano","qty":0.5,"unit":"g"},{"name":"Chilli flakes","qty":0.5,"unit":"g"},{"name":"Black pepper powder","qty":0.5,"unit":"g"},{"name":"Salt","qty":1,"unit":"g"}]$q$::jsonb, $q$["Boil the pasta in salted water 1 minute less than the packet says (usually 9–10 minutes). Keep 3 tbsp pasta water, then drain.","In the sauce pan melt half the butter, add garlic and onion and cook 2 minutes. Add bell peppers and corn and cook 2 minutes more (keep a crunch). Move to a plate.","Melt the rest of the butter on low, add the atta and stir 1 minute until it smells nutty (do not brown).","Pour in the milk slowly while whisking so no lumps form. Cook on low-medium 3–4 minutes, stirring, until it coats the back of a spoon.","Tear in the cheese slice and add the cream, salt, pepper, oregano and chilli flakes. Stir until smooth.","Add the pasta and vegetables and toss 1 minute. If thick, loosen with the saved pasta water."]$q$::jsonb, 10, 20, $q$Large pot for pasta, colander, heavy pan for the sauce, whisk$q$, $q$Portion is 100 g dry pasta. The sauce thickens as it cools in the box, so pack it slightly looser than you would serve at home. Contains gluten (wheat) and dairy.$q$)
  ) as v(code, ingredients, steps, prep, cook, equipment, tips)
  join public.menu_items m on m.code = v.code
on conflict (menu_item_id) do update
   set ingredients  = excluded.ingredients,
       steps        = excluded.steps,
       prep_minutes = excluded.prep_minutes,
       cook_minutes = excluded.cook_minutes,
       equipment    = excluded.equipment,
       tips         = excluded.tips;
